#include "core/InstrumentBody.h"
#include <cstdio>
#include <cstring>
#include <cstdint>
int main(int argc, char** argv){FILE* pcm = argc > 1 ? std::fopen(argv[1], "wb") : nullptr;for(int model=cs80::body::piano;model<=cs80::body::celesta;++model){std::uint64_t hash=1469598103934665603ULL;for(float note:{24.f,60.f,96.f})for(std::uint32_t seed:{42u,0x7812a3u,0xffffffffu}){cs80::body::InstrumentBody b;b.prepare(96000,48000);b.noteOn(model,note,.8f,.5f,1.f,seed);float f=440.f*std::exp2((note-69.f)/12.f);for(int i=0;i<8192;++i){float x=b.tick(f,.5f,i>2048?.5f:0.f);if (pcm) std::fwrite(&x, sizeof(x), 1, pcm);std::uint32_t bits;std::memcpy(&bits,&x,4);hash^=bits;hash*=1099511628211ULL;}}std::printf("%d %016llx\n",model,(unsigned long long)hash);}for(int model:{cs80::body::flute,cs80::body::piano,cs80::body::steel}){cs80::body::InstrumentBody b;b.prepare(96000,48000);b.noteOn(model,60,.8f,.5f,1.f,42);std::uint64_t hash=1469598103934665603ULL;for(int i=0;i<4096;++i){float x=b.tick(48000,.5f);if (pcm) std::fwrite(&x, sizeof(x), 1, pcm);std::uint32_t bits;std::memcpy(&bits,&x,4);hash^=bits;hash*=1099511628211ULL;}printf("noise %d %016llx\n",model,(unsigned long long)hash);}}
